/* From Uiverse.io by ercnersoy  - Tags: simple, switch, creative */
/* The switch - the box around the slider */
.__UIV_SCOPE__ .switch {
  font-size: 17px;
  position: relative;
  display: inline-block;
  width: 3.5em;
  height: 1.5em;
}
/* Hide default HTML checkbox */
.__UIV_SCOPE__ .switch input {
  opacity: 0;
  width: 0;
  height: 0;
}
/* The slider */
.__UIV_SCOPE__ .slider {
  position: absolute;
  cursor: pointer;
  inset: 0;
  background-color: #ccc;
  transition: 0.4s;
  border-radius: 1rem 0rem 1rem;
}

.__UIV_SCOPE__ .slider:before {
  position: absolute;
  content: "";
  height: 1.5em;
  width: 1.4em;
  left: 0em;
  bottom: 0em;
  background-color: white;
  transition: 0.4s;
  border-radius: 1rem 0rem 1rem;
  border: 3px solid white;
}

.__UIV_SCOPE__ .ch:checked + .slider {
  background-color: #72eb67;
}

.__UIV_SCOPE__ .ch:focus + .slider {
  box-shadow: 0 0 1px #2196f3;
}

.__UIV_SCOPE__ .ch:checked + .slider:before {
  transform: translateX(2.2em);
  background-color: green;
  box-shadow: 0px 0px 40px 5px #72eb67;
  border: 3px solid white;
}

.__UIV_SCOPE__ .ch:checked + .slider::after {
  content: "|";
  color: white;
  position: absolute;
  right: 0.3rem;
  top: -3.3px;
  transform: rotate(45deg);
}
